<footer class="relative bg-brand-cafe text-brand-bege-claro font-sans py-16 px-8">
  <div class="container mx-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-12 gap-10">
    <div class="lg:col-span-3">
      <h3 class="text-2xl font-serif text-brand-off-white mb-4"><?php the_field('nossa_historia_titulo', 'option'); ?></h3>
      <p class="text-sm leading-relaxed">
        <?php the_field('nossa_historia_texto', 'option'); ?>
      </p>
    </div>

    <div class="lg:col-span-3">
      <h3 class="text-2xl font-serif text-brand-off-white mb-4"><?php the_field('links_uteis_titulo', 'option'); ?></h3>
      <?php
        wp_nav_menu(array(
            'theme_location' => 'footer',
            'container'      => false,
            'menu_class'     => 'space-y-2', // Sua classe footerizada
        ));
      ?>
    </div>

    <div class="lg:col-span-3">
      <h3 class="text-2xl font-serif text-brand-off-white mb-4"><?php the_field('ultimas_postagens_titulo', 'option'); ?></h3>
      <div class="space-y-4">
        <?php
          $args = array(
              'post_type'           => 'post',  // O tipo de post (padrão)
              'posts_per_page'      => 3,  // Limite de 3 posts
          );

          $footer_posts_query = new WP_Query( $args );

          // Iniciar o Loop
          if ( $footer_posts_query->have_posts() ) :
              while ( $footer_posts_query->have_posts() ) : $footer_posts_query->the_post(); 
        ?>
        <a href="<?php the_permalink(); ?>" class="flex items-center gap-4 group">
          <div class="w-16 h-16 bg-brand-bg-section flex-shrink-0"></div>
          <p class="text-sm leading-snug group-hover:text-brand-off-white transition-colors">
            <?php the_title(); ?>
          </p>
        </a>
        <?php 
            endwhile;
          endif; 
          wp_reset_postdata();
        ?>
      </div>
    </div>

    <div class="lg:col-span-3 flex justify-center lg:justify-end items-start pt-6 lg:pt-0">
      <?php 
        $footer_logo = get_field('footer_logo', 'option');

        if ($footer_logo) : 
      ?>
        <a href="<?php echo esc_url( home_url( '/' ) ); ?>" rel="home">
          <img src="<?php echo esc_url($footer_logo['url']); ?>" alt="<?php echo esc_attr($footer_logo['alt']); ?>" class="w-48 h-auto">
        </a>
      <?php endif; ?>
    </div>
  </div>
  <?php wp_footer(); ?>
</footer>
